INSERT INTO feature VALUES('std-build','modules','The standard library''s manifest theories','packages','partial','ordinary',NULL,'`std.build` states the theories a manifest is read from: `Versioned` and `Toolchain`, which `Project` joins, `Presentation`, `Gandr.Package`, including `Project` and `Presentation`, and `Gandr.Workspace`, including `Project`, which a package source''s and a workspace''s models are of, and `Gandr.Module`, which no source models yet, and no type of a dependency, which an import''s coordinate names (#4527); every field of `Gandr.Package` but what it asks of the toolchain, its `name`, `version`, `authors`, `licence`, `documentation`, `endpoint`, `spelling` and `sources`, is inert, read only by the manifest step and another inert declaration, while `gandr`, `features` and `systems` are content; `authors`, `features` and `systems` are each one string until an operation''s port can be a list (#2993); a source under any root imports it by name, `import std.build (Gandr);`, a module path whose head `std` names the standard library wherever no source of the importer''s package does; `modelType` computes a presentation''s entries'' type, `encode` writes one `name = value` line for each constant, and the inert `render` writes a package model''s lines in the order of the presentation through the inert `packageEntries` of a model, one table with no escape (#4725).','surface-dispatcher surface-lowering','corpus/model/projects/hello/package.gandr corpus/model/projects/workspace.gandr corpus/model/projects/tools/package.gandr crates/surface-lowering/tests/namespace.rs::the_standard_package_theory_is_read_by_its_path_2767 crates/surface-dispatcher/src/component.rs::component::tests::a_fixture_imports_a_strict_source_and_not_the_reverse_2767 crates/surface-dispatcher/src/component.rs::component::tests::a_std_module_path_names_the_standard_library_from_any_root_4517 corpus/model/desc/module-reflection.gandr crates/surface-driver/tests/cli.rs::the_generic_render_writes_each_package_line_the_manifest_writes_6046','corpus/ledger/features/std-build.gandr','#2993');
